<?php
declare(strict_types=1);

/**
 * Affiliate products, second batch (30). ASINs researched on amazon.de on
 * 2026-10-10. Same rules as `affiliate.php`: no price, no image, no test
 * claims; price, partner link and cover arrive with the Amazon sync, and the
 * publish gate keeps each product a draft until they have.
 *
 * Several of these are embedded in the journal articles seeded by tds-ext-blog-cms
 * (`{{produkt:<slug>}}`). Renaming a slug here breaks that card silently.
 */

$p = static fn (string $category, string $asin, string $brand, string $tags, array $de, array $en): array => [
    'kind' => 'affiliate', 'category' => $category, 'asin' => $asin, 'brand' => $brand, 'tags' => $tags,
    'de' => $de, 'en' => $en,
];

$bodyDe = static fn (string $intro, array $good, array $watch, string $forWhom): string =>
    $intro . "\n\n## Was überzeugt\n\n- " . implode("\n- ", $good)
    . "\n\n## Worauf Sie achten sollten\n\n- " . implode("\n- ", $watch)
    . "\n\n## Für wen es passt\n\n" . $forWhom . "\n\nPreis und Verfügbarkeit sehen Sie beim Händler. Der Link ist ein Partnerlink.";
$bodyEn = static fn (string $intro, array $good, array $watch, string $forWhom): string =>
    $intro . "\n\n## What convinces\n\n- " . implode("\n- ", $good)
    . "\n\n## What to watch for\n\n- " . implode("\n- ", $watch)
    . "\n\n## Who it suits\n\n" . $forWhom . "\n\nPrice and availability are shown at the retailer. The link is an affiliate link.";

/** Compact constructor for one language. */
$t = static fn (string $slug, string $title, string $teaser, string $meta, string $summary, array $facts, array $faq, string $body): array => [
    'slug' => $slug, 'title' => $title, 'teaser' => $teaser, 'meta' => $meta, 'summary' => $summary,
    'facts' => array_map(static fn (array $f): array => ['label' => $f[0], 'value' => $f[1]], $facts),
    'faq' => array_map(static fn (array $f): array => ['q' => $f[0], 'a' => $f[1]], $faq),
    'body' => $body,
];

